var (
	unReservedKeywordTok = make(map[int]struct{}, len(unReservedKeywordNames))
	notKeywordTokenTok   = make(map[int]struct{}, len(notKeywordTokenNames))
	tidbKeywordTok       = make(map[int]struct{}, len(tiDBKeywordNames))
)

func init() {
	var missing []string
	build := func(dst map[int]struct{}, names []string) {
		for _, n := range names {
			if tok, ok := tokenMap[n]; ok {
				dst[tok] = struct{}{}
				continue
			}
			missing = append(missing, n)
		}
	}
	build(unReservedKeywordTok, unReservedKeywordNames)
	build(notKeywordTokenTok, notKeywordTokenNames)
	build(tidbKeywordTok, tiDBKeywordNames)
	if len(missing) > 0 {
		panic("keyword_classes.go: names missing from tokenMap: " + fmt.Sprint(missing))
	}
}

// isIdentifierTok reports whether tok can occupy identifier position:
//
//	Identifier: identifier | UnReservedKeyword | NotKeywordToken | TiDBKeyword
func isIdentifierTok(tok int) bool {
	if tok == identifier {
		return true
	}
	_, ok := unReservedKeywordTok[tok]
	if !ok {
		_, ok = notKeywordTokenTok[tok]
	}
	if !ok {
		_, ok = tidbKeywordTok[tok]
	}
	return ok
}
